import{_ as o,C as p,o as d,c as r,j as a,a as e,E as n,a3 as c}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"坐忘论·收心","description":"坐忘论第三篇精读（全篇最长）：收心离境、不著一物；不著于物，不滞于空，由作意安养而至自然无为。","frontmatter":{"title":"坐忘论·收心","description":"坐忘论第三篇精读（全篇最长）：收心离境、不著一物；不著于物，不滞于空，由作意安养而至自然无为。","category":"guide","aliases":["坐忘论收心","收心三","坐忘论精读之四"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-03.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-03.md","lastUpdated":1789714390000}'),g={name:"daoism/daoist-classics/zuowang-lun/chapter-03.md"};function h(u,s,b,v,m,x){const i=p("DaoReadingPrelude"),t=p("DaoTextReading"),l=p("DaoKeywordCards");return d(),r("div",null,[s[0]||(s[0]=a("h1",{id:"坐忘论·收心",tabindex:"-1"},[e("坐忘论·收心 "),a("a",{class:"header-anchor",href:"#坐忘论·收心","aria-label":'Permalink to "坐忘论·收心"'},"​")],-1)),n(i,{title:"心者一身之主，百神之帅",summary:"这是全书最长、理论最集中、也最重要的一篇。它讲收心离境、住无所有，同时逐一辨析偏差——执空、盲定、任心、口中无染。全篇的准绳是「息乱而不灭照，守静而不著空」，过程则是「随起随制，久久调熟，自得安闲」。",points:[{label:"先立心",text:"静则生慧，动则成昏——修行的第一处战场在这颗心上。"},{label:"再辨病",text:"执空、盲定、任心、口中无染，皆非真定。"},{label:"后归行",text:"法之妙用在能行不在能言；由有意安心渐至自然安闲。"}],hint:"此篇按内部层次分为六层；长文宜分段读，一段一段看它在解决哪一个问题。"}),s[1]||(s[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),s[2]||(s[2]=a("p",null,[a("strong",null,"一、心为身主")],-1)),n(t,{paragraphs:["夫心者一身之主，百神之帅，静则生慧，动则成昏。","欣迷幻境之中，唯言实是，甘宴有为之内，谁悟虚非，心识颠痴，良由所托之地。","且卜邻而居，犹从改操，择交而友，尚能致益，况身离生死之境，心居至道之中，能不舍彼乎，安不得此乎。","所以学道之初，要须安坐，收心离境，住无所有。","因住无所有，不著一物，自入虚无，心乃合道。","经云：至道之中，寂无所有，神用无方，心体亦然。","原其心体，以道为本，但为心神被染，蒙蔽渐深，流浪日久，遂与道隔。若净除心垢，开识神本，名曰修道。"]}),s[3]||(s[3]=a("p",null,[a("strong",null,"二、归根静定")],-1)),n(t,{paragraphs:["无复流浪，与道冥合，安在道中，名曰归根。守根不离，名曰静定。","静定日久，病消命复，复而又续，自得知常。知则无所不明，常则无所变灭，出离生死，实由于此。","是故法道安心，贵无所著。","经云：夫物芸芸，各归其根，归根曰静，静曰复命，复命曰常，知常曰明。","若执心住空，还是有所，非谓无所，凡住有所，则令心劳，既不合理，又反成病。","但心不著物，又得不动，此是真定。正基用此为定，心气调和，久益轻爽，以此为验，则邪正可知矣。"]}),s[4]||(s[4]=a("p",null,[a("strong",null,"三、四种错误收心法与真诀")],-1)),n(t,{paragraphs:["若心起皆灭，不简是非，则永断觉知，入于盲定。","若任心所起，一无收制，则与凡夫元来不别。","若唯断善恶，心无指归，肆意浮游，待自定者，徒自误尔。","若徧行诸事，言心无所染者，于言甚善，于行极非，真学之流，特宜诫此。","今则息乱而不灭照，守静而不著空，行之有常，自得真见。","如有时事或法要有疑者，且任思量，令事得济，所疑复悟，此亦生慧正根。","悟已则止，必莫有思，思则以智害恬，为子伤本。虽骋一时之俊，终亏万代之业。","若烦邪乱想，随觉则除，若闻毁誉之名，善恶等事，皆即拨去，莫将心受。","受之则心满，心满则道无所居。所有闻见，如不闻见，即是非善恶不入于心。","心不受外名曰虚心，心不逐外名曰安心，心安而虚，道自来居。","经云：人能虚心无为，非欲于道，道自归之。"]}),s[5]||(s[5]=a("p",null,[a("strong",null,"四、虚心安心")],-1)),n(t,{paragraphs:["内心既无所著，外行亦无所为，非净非秽，故毁誉无从生，非智非愚，故利害无由挠。","实则顺中为常，权则与时消息，苟免诸累，是其智也。","若非时非事，役思强为者，自云不著，终非真学。何耶？","心法如眼也，纤毫入眼，眼则不安，小事关心，心必动乱，既有动病，难入定门。"]}),s[6]||(s[6]=a("p",null,[a("strong",null,"五、除病如除荆棘")],-1)),n(t,{paragraphs:["是故修道之要，急在除病，病若不除，终难得定。","有如良田，荆棘未诛，虽下种子，嘉苗不茂。爱见思虑，是心荆棘，若不除翦，定慧不生。","或身居富贵，或学备经史，言则慈俭，行则贪残，辩足以饰非，势足以威物，得则名己，过则尤人，此病最深，虽学无益。"]}),s[7]||(s[7]=a("p",null,[a("strong",null,"六、调心之法")],-1)),n(t,{paragraphs:["所以然者，为自是故。然此心犹来依境，未惯独立，乍无所托，难以自安，纵得暂安，还复散乱。","随起随制，务令不动，久久调熟，自得安闲。","无问昼夜，行住坐卧，及应事之时，常须作意安之。","若心得定，即须安养，莫有恼触，少得定分，即堪自乐，渐渐驯狎，惟益清远。","平生所爱，已嫌蔽陋，况因定生慧，深达真假乎。","且牛马家畜也，放纵不收，犹自生梗，不受驾驭。鹰鹯野鸟也，为人羁绊，终日在手，自然调熟。况心之放逸，纵任不收，唯益粗疏，何能观妙。","经云：虽有拱璧，以先驷马，不如坐进此道。"]}),s[8]||(s[8]=a("p",null,[a("strong",null,"七、能行不在能言")],-1)),n(t,{paragraphs:["夫法之妙用也，其在能行，不在能言，行之则斯言为当，不行则斯言如妄。","又时人所学，贵难而贱易，若论法要，广说虚无，思虑所莫能达，行用所莫能阶者，则叹不可思议。","而下风尽礼，如其信言不美，指事直说，闻则心解，言则可行者，此实不可思议，而人翻以为浅近，而轻忽不信。","经云：吾言甚易知，甚易行，天下莫能知，莫能行。夫惟无知，是以不我知。","又有言火不热，灯不照暗，称为妙义。夫火以热为用，灯以照暗为功。","今则盛谈火不热，未尝一时废火，灯不照暗，必须终夜然灯。言行相违，理实无取，此即破相之言，而人反以为深玄之妙。","虽惠子宏辩，庄生以为不堪。肤受之流，谁能断简，至学之士，庶不留心。"]}),s[9]||(s[9]=a("p",null,[a("strong",null,"八、问答：动静取舍")],-1)),n(t,{paragraphs:["或曰：夫为大道者，在物而心不染，处动而神不乱，无事而不为，无时而不寂。今独避事而取安，离动而求定，劳于控制，乃有动静二心，滞于住守，是成取舍两病。都未觉其外执，而谓道之阶要，何其谬邪。","答曰：总物而称大，通物之谓道，在物而不染，处事而不乱，真为大矣，实为妙矣。","然谓吾子之鉴有所末明，何耶？徒见贝锦之辉焕，未晓始抽之素丝，才闻鸣鹤之冲天，讵识先资于𬆮食。","蔽日之干，起于毫末。神凝至圣，积习而成。","今徒学语其圣德，而不知圣之所以德，可谓见卯而求时夜，见弹而求鸮炙。何其造次哉。","故经云：玄德深矣，远矣，与物反矣。然后乃至大顺。"]}),s[10]||(s[10]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[e("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(l,{items:[{term:"心识颠痴",pinyin:["xīn","shí","diān","chī"],meaning:"心识，认识、分别、记忆与执取的活动；颠，以假为真、以苦为乐；痴，不能照见真实。谓心之颠倒愚痴。"},{term:"所托之地",pinyin:["suǒ","tuō","zhī","dì"],meaning:"心所依托、安放、寄居的对象或境界。心托于名则随毁誉而动，托于利则随得失而动——收心即是改变心的立足之地。"},{term:"住无所有",pinyin:["zhù","wú","suǒ","yǒu"],meaning:"使心安住于不占有、不依附任何对象的状态。非世界不存在，也非进入空白麻木，而是无所依而能住，无所有而不散。"},{term:"神用无方",pinyin:["shén","yòng","wú","fāng"],meaning:"幽微灵妙的作用没有固定方向、形式与边界。道体寂而无所有，道用则神妙无方。"},{term:"心垢",pinyin:["xīn","gòu"],meaning:"附着于心、使心失去清明的贪爱、成见、杂念与执著。是后天积累的遮蔽，非心体本身。"},{term:"开识神本",pinyin:["kāi","shí","shén","běn"],meaning:"开明其识，显发心神本有的根源（即「以道为本」）。修道的定义由此确立：净除心垢，使神本重新显明。"},{term:"盲定",pinyin:["máng","dìng"],meaning:"若心起皆灭、不简是非，则永断觉知，如盲者之定。看似无念，却无清楚觉照——与真定相对。"},{term:"息乱而不灭照",pinyin:["xī","luàn","ér","bù","miè","zhào"],meaning:"止息纷乱攀缘，但不熄灭清醒觉照。乱要息，照不可灭；念可不随，觉不可昏。本篇总诀之一。"},{term:"守静而不著空",pinyin:["shǒu","jìng","ér","bù","zhuó","kōng"],meaning:"安住于静，却不把「静」或「空」当作可执著的对象。守静防散乱，不著空防僵滞。"},{term:"虚心",pinyin:["xū","xīn"],meaning:"心不受外名曰虚心——不把见闻毁誉纳进来反复保存，解决「被占满」的问题。"},{term:"安心",pinyin:["ān","xīn"],meaning:"心不逐外名曰安心——不追随外境奔逸，解决「向外流浪」的问题。必须安而且虚。"},{term:"爱见思虑",pinyin:["ài","jiàn","sī","lǜ"],meaning:"爱，贪爱依恋；见，固执见解尤其是自以为是；思虑，无休止的分别盘算。三者相续，本篇喻为「心荆棘」。"},{term:"役思强为",pinyin:["yì","sī","qiǎng","wéi"],meaning:"役使思虑、勉强造作。谓非时非事而强行用思，虽自称不著，终非真学。"},{term:"随起随制",pinyin:["suí","qǐ","suí","zhì"],meaning:"念头一生起即随即收摄制止。重点不在禁止念头最初出现，而在阻止它继续扩展——比「心起皆灭」温和，比「任心所起」积极。"},{term:"驯狎",pinyin:["xùn","xiá"],meaning:"驯，调伏；狎，亲近熟习。渐渐驯狎，谓心经长期调习而渐熟，非以暴力压制。"},{term:"鹰鹯",pinyin:["yīng","zhān"],meaning:"鹰与鹯，皆猛禽。取「野鸟久被羁绊亦能调熟」为喻，说心虽放逸亦可调习——古代调心之喻。"},{term:"贝锦",pinyin:["bèi","jǐn"],meaning:"织成贝纹的锦。此处喻徒见其成而不见其始：只见圣人动静一如之果，不知其积习之因。"},{term:"𬆮食",pinyin:["kòu","shí"],meaning:"依底本保留。结合文意指幼鸟成长阶段所需的饮食滋养（相关版本或有异文）。鸣鹤冲天，先资于𬆮食。"},{term:"见卯而求时夜",pinyin:["jiàn","mǎo","ér","qiú","shí","yè"],meaning:"底本作「卯」，常见文字作「卵」（见卵而求时夜）。时夜即司晨之鸡。见卵便求报晓之鸡，喻求成太急、不知次序。"},{term:"见弹而求鸮炙",pinyin:["jiàn","dàn","ér","qiú","xiāo","zhì"],meaning:"鸮炙即烤鸮鸟肉。见弹丸便想烤肉，同喻急求其成。"}]}),s[11]||(s[11]=c(`<h2 id="【解读层】精读" tabindex="-1">【解读层】精读 <a class="header-anchor" href="#【解读层】精读" aria-label="Permalink to &quot;【解读层】精读&quot;">​</a></h2><h3 id="全篇结构与六层读法" tabindex="-1">全篇结构与六层读法 <a class="header-anchor" href="#全篇结构与六层读法" aria-label="Permalink to &quot;全篇结构与六层读法&quot;">​</a></h3><p>【收心】是《坐忘论》七篇中篇幅最长、理论最集中、也最重要的一篇。前两篇完成了准备：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>敬信：确定修道的方向</span></span>
<span class="line"><span>断缘：减少外部关系与事务的牵引</span></span>
<span class="line"><span>收心：直接处理内在不断逐境的心</span></span></code></pre></div><p>但外缘减少以后，心并不会立刻安静——它长期依赖外境，已养成追逐、分别、回忆与筹划的习惯；一旦暂时无事，反而可能无所适从。因此<strong>断缘只是撤去部分外因，收心才是真正进入内在训练</strong>。</p><p>全篇分为六层：</p><table tabindex="0"><thead><tr><th>层</th><th>范围（首句 → 末句）</th><th>核心问题</th></tr></thead><tbody><tr><td>一 · 心为何必须离境归道</td><td>「夫心者一身之主」→「名曰修道」</td><td>心为何是一身之主？为何会迷失？「安坐」「离境」「住无所有」何意？</td></tr><tr><td>二 · 归根静定与真正的无所著</td><td>「无复流浪」→「邪正可知矣」</td><td>何谓归根、静定、复命、知常？为何「执心住空」仍是有所著？</td></tr><tr><td>三 · 四种错误方法与收心正诀</td><td>「若心起皆灭」→「道自来居」</td><td>为何不能一概灭念？「息乱而不灭照」何意？虚心、安心是什么？</td></tr><tr><td>四 · 心病、荆棘与「自是」之患</td><td>「内心既无所著」→「虽学无益」</td><td>心法为何如眼？爱见思虑为何是荆棘？「自是」为何病最深？</td></tr><tr><td>五 · 长期调心与行住坐卧的安养</td><td>「所以然者，为自是故」→「不如坐进此道」</td><td>心为何不能立时独立？「随起随制」是不是压制？</td></tr><tr><td>六 · 贵行贱言，初学不可冒充圣境</td><td>「夫法之妙用也」→ 篇末</td><td>法为何贵行不贵言？为何不能直接模仿圣人的动静一如？</td></tr></tbody></table><p>总路线：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心本以道为根</span></span>
<span class="line"><span>    ↓ 因长期依境而受染</span></span>
<span class="line"><span>先安坐离境，收摄外驰</span></span>
<span class="line"><span>    ↓ 不著物，也不著空</span></span>
<span class="line"><span>息乱而保留觉照</span></span>
<span class="line"><span>    ↓ 随起随制，久久调熟</span></span>
<span class="line"><span>由有意安心得到自然安闲</span></span>
<span class="line"><span>    ↓ 由静生定，由定生慧</span></span>
<span class="line"><span>最终在物不染、处事不乱</span></span></code></pre></div><h3 id="一、心为何必须离境归道-第一层" tabindex="-1">一、心为何必须离境归道（第一层） <a class="header-anchor" href="#一、心为何必须离境归道-第一层" aria-label="Permalink to &quot;一、心为何必须离境归道（第一层）&quot;">​</a></h3><p><strong>心者一身之主，百神之帅</strong>——此「心」不单指心脏或思考能力，而是包括感知、意念、情绪、欲望、记忆、判断、注意与自我意识的综合概念。身之行动通常受心支配：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心有所爱 → 身体便向它追逐</span></span>
<span class="line"><span>心有所恶 → 身体便想逃避或对抗</span></span>
<span class="line"><span>心神安定 → 形体活动也较为和缓</span></span></code></pre></div><p>「百神」是道教人体观中身内诸神的总称，也可宽泛理解为各种精神与生命机能；「帅」是统领者。心神若安，各种机能各安其位；心神若乱，整个生命秩序受到扰动。故<strong>收心不是只处理几个杂念，而是在重新整顿整个身心秩序</strong>。</p><p>但不能把心理解为体内一个固定不变的小人在发号施令——本篇后文仍要求不著一物、不执心住空、不以智为主、忘形忘我。<strong>「心为主帅」是在说明心的统摄作用，而不是建立一个永恒实体的「我」。</strong></p><p><strong>静则生慧，动则成昏</strong>——「生」不是从无到有地制造智慧（《泰定》明说「慧出本性，非适今有」），而是遮蔽减弱后慧自然显露，如水面平静方能映照。这里的「动」也不是所有心理活动，而主要指见物即逐、遇事即黏、念念迁流、被毁誉得失牵引。心一旦被欲望占据，观察时便不再只是看事物本身，而是在看它对我是否有利、是否满足期待、是否威胁身份——<strong>于是心越活跃，未必越清明，有时只是更有效率地维护自己的执著</strong>。</p><p>静与动首先是心的状态，不是身体姿势：</p><table tabindex="0"><thead><tr><th>外在状态</th><th>内在可能状态</th></tr></thead><tbody><tr><td>身体静坐</td><td>心中不断回忆、幻想，仍属动</td></tr><tr><td>身体行动</td><td>因事而应，事毕即止，可以相对静</td></tr><tr><td>表面无事</td><td>不断寻找刺激，仍不安静</td></tr><tr><td>正在思考</td><td>为解决必要问题而思，未必是乱动</td></tr></tbody></table><p>不过初学者外在静止仍很重要，故后文说「学道之初，要须安坐」。</p><p><strong>欣迷幻境之中，唯言实是</strong>——「幻」不是说外在世界不存在，而是说事物不断变化、名位不能恒常、关系会亲疏、快感短暂即逝，却被心当作可靠归宿。「欣迷」比被迫迷失更深一层：人不但陷在其中，甚至喜欢这种陷入。「实是」就是把暂时、因缘而成的东西看成真实固定：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>暂时的称赞 → 被看成我的真实价值</span></span>
<span class="line"><span>一时的职位 → 被看成固定身份</span></span>
<span class="line"><span>一个念头   → 被看成真实的我</span></span></code></pre></div><p>心之所以被外境束缚，不只因为外境出现，更因为<strong>心赋予它绝对真实性</strong>。故「收心离境」不是否认一切事物，而是不再把变动之境当作生命的固定根本。</p><p><strong>甘宴有为之内，谁悟虚非</strong>——「有为」在此是不断借行动确认、扩张自我的过程（获得更多、控制更多、被更多人看见、用结果证明自己）。人之所以「甘宴」其中，是因为有为会产生强烈感受：「我正在做事，我能够控制，我正在进步。」而「虚非」不能理解为「一切都是假的，所以什么都不必做」——「虚」是说它不能作为恒常依靠，「非」是说它不是生命的真实归宿：<strong>可以因事而行，但不可把它当作真实自我和永恒归宿。</strong></p><p><strong>心识颠痴，良由所托之地</strong>——心的认识之所以颠倒愚痴，是因为把不可靠的境界当成了可靠归宿。这是本段的关键判断：心长期寄托于什么，就会受什么影响。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心托于名 → 随毁誉而动</span></span>
<span class="line"><span>心托于利 → 随得失而动</span></span>
<span class="line"><span>心托于关系 → 随亲疏而动</span></span>
<span class="line"><span>心托于大道 → 逐渐清静、安定、无著</span></span></code></pre></div><p>所以收心不只是减少念头，而是<strong>改变心的立足之地：从依境而住，转为依道而安</strong>。（后文又说「不依一物」，并不矛盾：初学以道为方向、离开错误依托；深入以后，连「道是一个可供我依附的对象」这种观念也要放下。）</p><p><strong>卜邻而居，择交而友</strong>——即使只是选择邻居居住，人的操行尚且会随环境改变；选择朋友交往，尚且能带来益处。司马承祯借此说明一个朴素规律：<strong>长期接触什么，心就容易习惯什么。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>住处和邻居尚且能改变操行</span></span>
<span class="line"><span>朋友和交往尚且能影响心志</span></span>
<span class="line"><span>何况心长期居住的境界，更会决定心的状态</span></span></code></pre></div><p>如果心终日居于名利得失、毁誉比较、欲望想象、过去追悔、未来焦虑，即使身体处在静室，心仍住在俗境之中。所以【断缘】正是在调整心的「所托之地」。</p><p><strong>身离生死之境，心居至道之中</strong>——「生死之境」不必只理解为肉身生死，也包括一切使心反复陷入得失、爱恶与造业循环的境界。「心居至道」不是不断想着「道」这个字，而是让心逐渐具有与道相应的品质（清静、无欲、不争、虚而能应、来而不迎去而不留）。这不是一次性的意志决断，而是<strong>长期更换心所依托的环境</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>身逐渐离开妨道环境 + 心长期安住清静之道</span></span>
<span class="line"><span>        ↓ 旧有习惯失去外缘支持，新的安定不断得到培养</span></span>
<span class="line"><span>自然渐舍彼境、渐得此道</span></span></code></pre></div><p><strong>学道之初，要须安坐</strong>——这是《坐忘论》第一次明确提出「安坐」。它不是说修道永远只能坐着，而是承认初学的现实：心还没有稳定能力，一边处理复杂事务一边声称不染，容易成为自欺。安坐是一种训练环境：身体暂时不向外行动，外界事务暂时停止，注意力不再不断转换，内心原有活动开始显露。</p><p>重点在「<strong>安</strong>」：环境相对安静、姿势稳定而不过度紧张、呼吸自然、暂无必须立即处理之事、不急于追求特殊状态。这与《天隐子·安处》直接相应。</p><p><strong>收心离境</strong>——是一件事的两面：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从心的角度说：停止向外追逐，叫收心</span></span>
<span class="line"><span>从境的角度说：不再黏著对象，叫离境</span></span></code></pre></div><p>「离境」不等于外界从感官中消失，而是不再跟随它继续展开：听到声音→知道有声音→不继续判断、联想和追逐。这与《天隐子·坐忘》「有见而不行其见」高度一致。</p><p><strong>住无所有</strong>——最容易被误解的一句。它不是说世界什么都不存在，也不是要求进入黑暗、空白或麻木，而是：不把任何感觉据为所有，不把任何念头认作固定的我，不把任何境界当作必须维持的状态，不寻找一个对象供心依附。于是出现一个看似矛盾、其实非常重要的结构：</p><blockquote><p><strong>无所依而能住，无所有而不散。</strong></p></blockquote><p>《枢翼》说得更清楚：「不依一物，而心常住。」但「无所有」也不是执著于空白——若心努力维持空白感、害怕念头出现、把「空」当作修行成就，那么「空」本身又成了新的「所有」。这正是下一层马上要讨论的「若执心住空，还是有所」。</p><p><strong>不著一物，自入虚无，心乃合道</strong>——「物」不仅指外物，也包括感官对象、念头、情绪、观念、空境、修行体验与「我很清静」的自我评价。「不著」不是不许它出现，而是出现之后不抓住。</p><p>「<strong>自入</strong>」二字十分重要：虚无不是靠强迫制造出来的，而是攀缘停止后自然呈现。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误方向：努力制造空白 → 压制念头 → 越紧张 → 更不安</span></span>
<span class="line"><span>正确方向：不追逐所现之物 → 不再续接念头 → 负担自然减少 → 虚静自行显露</span></span></code></pre></div><p>心若执著一物，便被限定在这一物上；心若无所著，才可能与无方之道相应。</p><p><strong>至道之中，寂无所有，神用无方</strong>——道同时具有两面：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>体：寂无所有（非死寂，而是无私意躁动；非不存在，而是无固定形体）</span></span>
<span class="line"><span>用：神妙无方（能随物而应）</span></span></code></pre></div><p>「心体亦然」——心的本来状态同样是「其体虚静，无固定所有；其用灵明，能够随事而应」。问题不在心没有能力，而在它被某些对象占据以后，失去了本来的无方妙用：心被愤怒占据，只能从敌意理解事物；心被名声占据，只在乎别人如何评价。<strong>所以收心不是削弱心的功能，而是解除其局限。</strong></p><p><strong>原其心体，以道为本</strong>——这奠定了《坐忘论》的心性立场：人的心并非从根本上与道敌对，也不是本质上只有贪欲散乱。心能够清静、觉照、与道冥合，是因为它本来便以道为根，所以修行具有可能性。这与开篇「人之有道，若鱼之有水」彼此呼应，也与《天隐子·神仙一》「禀得灵气」相应——<strong>修道不是外加一个新本性，而是恢复原有的灵明。</strong></p><p><strong>心为什么会与道相隔</strong>——「心神被染」指心长期接触、追逐某种境界后被它改变原本状态；染污不一定来自极端恶行，日常的反复也足以形成（习惯性比较、对评价的敏感、对信息刺激的依赖）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次随境 → 留下一点习惯</span></span>
<span class="line"><span>反复随境 → 习惯越来越强</span></span>
<span class="line"><span>习惯成为默认反应 → 心不再察觉自己正在逐境</span></span></code></pre></div><p>「蒙蔽渐深」说明染污由积习而深，故清静也要由积习而复——不能要求长期形成的心行在一次静坐中彻底改变。「流浪日久」则生动地描画出心没有固定安处、不断从一个对象转到另一个对象：从声音到形色、从形色到记忆、从计划到忧虑，看似活动丰富，实际没有真正归宿。这与总论的「弱丧」（离乡日久、不知归路）相呼应。</p><p>「遂与道隔」主要是遮蔽意义上的隔，不是说人与道在本体上彻底分离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乌云遮日 ≠ 太阳已经消失</span></span>
<span class="line"><span>心垢蔽道 ≠ 心的根本已被毁灭</span></span></code></pre></div><p>正因为只是被染、被蒙蔽，下面才有「净除」「开识」的可能。</p><p><strong>什么才叫「修道」</strong>——「若净除心垢，开识神本，名曰修道」给出了非常重要的定义：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心体：本以道为根</span></span>
<span class="line"><span>心垢：依境外驰形成的习惯与执著</span></span></code></pre></div><p>修行所除的是<strong>心垢</strong>，不是把心本身消灭。因此收心不是消灭感知、智慧与正常情感，使人麻木；所除的是使这些功能失去平衡的黏著与妄动。「开识神本」不是通过概念推论得出「我有神本」，而是在实际收心中逐渐体验到：心可以不被念头完全支配、外境出现不一定必须追随、欲望暂息后觉照仍然存在、无所著时心并不因此断灭。</p><blockquote><p><strong>修道不是修饰一个本来错误的自我，而是净除心垢，使本来以道为根的心神重新显明。</strong></p></blockquote><p>「修」因此有两义：<strong>修除</strong>（外驰、黏著、爱恶、成见、机心）与<strong>修复</strong>（虚静、灵明、安定、无著、与道相应）。道不待人制造，心本不离于道；所修的是遮蔽，所复的是本根。</p><h3 id="二、归根、静定、复命与知常-第二层" tabindex="-1">二、归根、静定、复命与知常（第二层） <a class="header-anchor" href="#二、归根、静定、复命与知常-第二层" aria-label="Permalink to &quot;二、归根、静定、复命与知常（第二层）&quot;">​</a></h3><p><strong>无复流浪，与道冥合，安在道中，名曰归根</strong>——上一段以「流浪」形容心不断逐境，这里以「归根」表示结束漂泊。前文已说「原其心体，以道为本」，所以<strong>归根就是心从外境返归其以道为本的状态</strong>。「与道冥合」的「冥」尤其重要：不是强烈地想着「我正在与道合一」，而是在不知不觉、无所造作中相合。</p><p><strong>守根不离，名曰静定</strong>——</p><table tabindex="0"><thead><tr><th>阶段</th><th>含义</th></tr></thead><tbody><tr><td>归根</td><td>心从外驰中返回</td></tr><tr><td>静定</td><td>返回以后，能够安住而不再轻易离失</td></tr></tbody></table><p>偶尔获得片刻清静，并不等于已经得定。真正的「定」包含稳定性：念头虽起不会立刻随之而走，外境虽现不会完全夺去心神，清静不再完全依赖某一特定感觉。不过这里的「守」仍带有初步用功的意味，功夫纯熟以后才进入【泰定】的「无心于定，而无所不定」。</p><p><strong>静定日久，病消命复</strong>——「病」首先指心病（贪爱、怨憎、妄想、机心、自是、随境迁流）。心病既能扰乱精神，也可能进一步影响气息与形体，故「病消命复」有心性与养生两层含义：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心不再妄动 → 神气减少耗散 → 形神逐渐调和 → 本有生命秩序得以恢复</span></span></code></pre></div><p>但不宜理解为静坐必然治愈一切身体疾病：原文表达的是传统道教形神相应的修炼观，不能替代现实中的医疗判断。</p><p><strong>复而又续，自得知常</strong>——偶尔静一次，不能称为「知常」。只有不断返回、不断安住，才会逐渐看见：念头虽来去而觉照不必随之迁流，得失毁誉都是暂时变化，清静无著比具体境界更接近生命根本。「知常」不是背诵一个关于「常」的定义，而是通过反复实践，认识什么是变化的、什么是不应随变化而失守的。</p><p>「知则无所不明，常则无所变灭」也不能理解为得定后知晓一切具体知识：「无所不明」主要是说不再因个人爱恶而严重扭曲判断（心著于利只看见有利的一面，心著于名只看见别人如何评价，心虚而静才可能如实观察）；「无所变灭」则是说心神所归的道不随外境起伏而生灭。</p><p>「出离生死，实由于此」的完整次第是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无复流浪 → 与道冥合 → 归根</span></span>
<span class="line"><span>守根不离 → 静定</span></span>
<span class="line"><span>静定日久 → 心病渐消 → 复命</span></span>
<span class="line"><span>复而又续 → 知常</span></span>
<span class="line"><span>知常而明 → 不再随境造业 → 逐渐出离生死</span></span></code></pre></div><p>这说明「出离生死」不是由想象某个神秘境界得到，而要落实为心念、习惯与行为方向的改变。</p><p><strong>引《道德经》第十六章</strong>——「夫物芸芸，各归其根，归根曰静，静曰复命，复命曰常，知常曰明」（通行本作「各复归其根。归根曰静，是谓复命」）。《老子》原本观察万物盛衰循环（万物纷纭生长→各自返归根本→归根便是静→静即复命→复命即常→知常即明），司马承祯把这一宇宙论转化为调心次第：<strong>万念纷纭 → 收心离境 → 归根 → 静定 → 复命 → 知常</strong>。人心的返归，被置于万物自然返根的秩序之中。</p><p><strong>不著于物，也不能执著于空</strong>——「若执心住空，还是有所」是对上一层「住无所有」的重要纠偏。修行者听说「不著一物」，很容易把「空」当作新的对象（努力维持无念、害怕声音和念头出现、认为只有特定状态才是定）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执著于物 → 被物束缚</span></span>
<span class="line"><span>执著于空 → 被空束缚</span></span>
<span class="line"><span>物与空不同 → 执著的心理结构却相同</span></span></code></pre></div><p>真正的「无所著」不是从「有」逃到「空」，而是不被有、无任何一端固定。「凡住有所，则令心劳」：只要心在想「我必须守住这个状态」「我绝不能起念」，它就需要持续监督、压制和维持。<strong>真正的定不应依靠长期紧绷</strong>——若越静坐越紧张、越害怕被打扰，就说明心仍在用力抓住某种境界。</p><p>「既不合理，又反成病」——前文说道「寂无所有，神用无方」，若把定理解为僵死、空白、拒绝一切变化，就只取了「寂」而失去「神用」；过度束心则可能导致精神紧张、对念头产生恐惧、强迫性自我监控、昏沉木然，甚至把麻木误认为安定。《枢翼》后来也强调收心必须「宽急得中」。</p><p><strong>但心不著物，又得不动，此是真定</strong>——真定必须同时满足两个条件：</p><table tabindex="0"><thead><tr><th>条件</th><th>所防止的偏差</th></tr></thead><tbody><tr><td>不著物</td><td>防止攀缘、黏著</td></tr><tr><td>又不动</td><td>防止散乱、放逸</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不著而不散，不动而不僵，寂静而有觉照，无住而能安住</span></span></code></pre></div><p><strong>心气调和，久益轻爽，以此为验</strong>——司马承祯没有把奇异景象作为验证标准，而把「心气调和、久益轻爽」作为较可靠的征验：正确收心通常使人心更安稳、气息更自然、情绪反应较柔和、觉知更清明；错误方法则可能使人越练越紧张、越来越执著境界、昏沉麻木。这呈现出《坐忘论》非常实际的一面：</p><blockquote><p><strong>判断方法是否正确，不看是否玄妙，而看是否使心气趋于调和。</strong></p></blockquote><h3 id="三、四种错误收心法与真正正诀-第三层" tabindex="-1">三、四种错误收心法与真正正诀（第三层） <a class="header-anchor" href="#三、四种错误收心法与真正正诀-第三层" aria-label="Permalink to &quot;三、四种错误收心法与真正正诀（第三层）&quot;">​</a></h3><p><strong>第一种：心起皆灭</strong>（「若心起皆灭，不简是非，则永断觉知，入于盲定」）——若凡有念头生起便一概消灭，不分必要与不必要，就会断绝清醒觉知。有些念头属于必要事务的判断、对修法疑问的辨明、对危险的正常觉察；若不加分辨而全部压灭，修行就不再是清明，而是迟钝。「盲定」的特征是：看似没有念头，却没有清楚觉照；看似非常安静，却不能如实辨别。<strong>故《坐忘论》不以「念头数量最少」为标准，而以「乱念止息、觉照仍明」为标准。</strong></p><p><strong>第二种：任心所起</strong>（「若任心所起，一无收制，则与凡夫元来不别」）——若任凭一切念头自然生起、完全不加收摄，就与未经修习的普通状态没有区别。心长期逐境已形成强大惯性，若完全顺从，只会继续走原来的路线：念起→联想→情绪→欲望→行动→新的习惯。<strong>初学需要「收制」，但收制不是暴力消灭，而是不让念头继续扩展。</strong></p><p><strong>第三种：唯断善恶，肆意浮游</strong>（「若唯断善恶，心无指归，肆意浮游，待自定者，徒自误尔」）——要区别两个层次：得道者不以个人好恶扭曲事物，不执著善恶之名（超越善恶分别）；初学者若借「无分别」之名任心放逸，实际只是没有原则。真正的无分别，是经过定慧以后不受爱憎支配，并不是初学时取消判断、任由习气活动。故初学仍需要明确方向：从外驰转向返照、从黏著转向不著、从散乱转向安定。</p><p><strong>第四种：徧行诸事，自称不染</strong>（「若徧行诸事，言心无所染者，于言甚善，于行极非」）——理论上得道者确实可以在物不染、处事不乱，但初学者若借这一最高境界为自己的放逸辩护，便容易成为自欺：明明受毁誉影响却说「我不执著」，明明事务使心散乱却说「动静一如」。故「真学之流，特宜诫此」——<strong>真正学习修道的人，尤其应防止用高深语言掩盖实际定力不足。</strong></p><p><strong>正诀：息乱而不灭照，守静而不著空</strong>——</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>息乱，防止放逸；不灭照，防止昏沉</span></span>
<span class="line"><span>守静，防止散乱；不著空，防止僵滞</span></span></code></pre></div><p>所息的是无意义的联想、反复盘旋的忧虑、对毁誉的持续反应；所保留的是对当前身心状态的觉察、对必要事务的判断。这两句可视为《收心》全篇的总诀。</p><p>「行之有常，自得真见」——「真见」不是通过强烈思辨制造出来，而是心静以后对事物的虚实、轻重与因果看得更清楚。关键不在偶尔一次深度体验，而在日日收心、念起即觉、觉而不随、行住坐卧皆不完全放失。这里已从「定」过渡到「慧」。</p><p><strong>必要思考与有害思虑如何区分</strong>——「如有时事或法要有疑者，且任思量」：「《坐忘论》并不反对所有思考。」必要的思量具有明确对象和终点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正当思考：有具体问题 → 必要思量 → 得出可行处理 → 问题解决 → 思考停止</span></span>
<span class="line"><span>妄想：    没有当前问题 → 反复设想 → 引出更多利害 → 情绪增长 → 没有完成时刻</span></span></code></pre></div><p>区别不在「有没有念头」，而在它是否必要、有限并能适时停止。「此亦生慧正根」再次证明「黜聪明」不是反对正常智慧。「悟已则止，必莫有思」——不是永远禁止思考，而是<strong>问题解决以后不再以思考本身为乐</strong>（反复复盘、想象另一种结果、证明自己当时正确）。「思则以智害恬，为子伤本」：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常：恬静 → 生智慧 → 解决必要问题 → 重新归于恬静</span></span>
<span class="line"><span>错误：恬静生智慧 → 因智慧而好辩逞能 → 思虑越来越多 → 反过来破坏恬静</span></span></code></pre></div><p>「虽骋一时之俊，终亏万代之业」——炫示聪明可能带来短期赞誉，却重新加强好胜心、自我意识与对名声的依赖。<strong>真正困难的不是生慧，而是有慧之后不以慧扰定</strong>——这正是【泰定】「非生慧难，慧而不用难」的前奏。</p><p><strong>烦邪乱想与毁誉见闻怎样处理</strong>——「随觉则除」可拆成两步：随起而觉（看见念头已经出现）、随觉而除（不认同、不续接、不付诸行动）。「除」不是激烈驱赶——越与念头搏斗，越可能强化它；更准确地说，是<strong>撤去对念头的注意、认同与继续加工</strong>。</p><p>「若闻毁誉之名、善恶等事，皆即拨去」——并非取消事实判断（若确需处理，前文已允许「且任思量」），所要拨去的是与自己无关却引人议论的是非、对他人善恶的反复评判、听赞誉后不断回味、听毁谤后长期愤怒。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>耳朵听见一句话 → 属于自然见闻</span></span>
<span class="line"><span>心不断回想、辩解、怨恨 → 才成为「受」</span></span></code></pre></div><p>「受之则心满，心满则道无所居」——「心满」不是内容丰富，而是被各种名相塞住：满是自我辩护、别人评价、未完成计划、恩怨是非。「所有闻见，如不闻见」不是装作不知道，更不是故意忽视必须处理的问题，而更接近镜心：来则照见、去则不藏。</p><p><strong>虚心与安心</strong>——两条非常精确的定义：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>虚心：心不受外 → 心中不满 → 故能虚（解决「被占满」）</span></span>
<span class="line"><span>安心：心不逐外 → 心不迁流 → 故能安（解决「向外流浪」）</span></span></code></pre></div><p>虚而不安，可能仍然漂浮散乱；安而不虚，可能执著于某种境界。<strong>必须「安而且虚」</strong>。「心安而虚，道自来居」——不是把道从外面搬进心里，而是外驰与遮蔽减少后，心本来与道相应的性质自然显露，所以强调「自来」而非强求。</p><h3 id="四、内无所著-外无所为-心法如眼与心中荆棘-第四层" tabindex="-1">四、内无所著，外无所为；心法如眼与心中荆棘（第四层） <a class="header-anchor" href="#四、内无所著-外无所为-心法如眼与心中荆棘-第四层" aria-label="Permalink to &quot;四、内无所著，外无所为；心法如眼与心中荆棘（第四层）&quot;">​</a></h3><p><strong>内心既无所著，外行亦无所为</strong>——</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内无贪著 → 外不强作</span></span>
<span class="line"><span>事来则应 → 不额外制造</span></span>
<span class="line"><span>事毕即止 → 不系心为业</span></span></code></pre></div><p><strong>非净非秽，故毁誉无从生</strong>——若执著「我是清净修道者」，就会害怕别人说自己不清净；越是依赖清高形象，越容易受毁誉影响。「非净非秽」不是混淆净秽，而是不以净秽名相建立固定自我。同理，「非智非愚，故利害无由挠」：若执著「我很聪明」便会不断证明自己，若故意装愚以求清高仍是造作。</p><p><strong>实则顺中为常，权则与时消息</strong>——通常情形依循中正之道，遇到特殊情况随时势灵活应对。这说明坐忘并不培养僵化的人：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有常道，但不死守形式；能权变，但不借权变纵欲</span></span></code></pre></div><p>「苟免诸累，是其智也」——只要权变不使心重新陷入牵累，这就是合宜的智慧。</p><p><strong>心法如眼</strong>——「若非时非事，役思强为」提示：判断一件事是否妨道，不只看事情大小，还要看是否当时、是否必要、是否出于强为、是否长期关心。许多使心散乱的，并非重大事件，而是大量「非时非事」的微小关注。</p><p>「心法如眼也，纤毫入眼，眼则不安」——眼睛极其敏感，异物再小也影响视力；心同样如此。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事情很小 + 心长期黏著 = 扰动很大</span></span></code></pre></div><p>因此修心不能只戒除明显的大欲望，也要看见细微的期待、不服、辩解、比较、对赞美的回味、对轻微冒犯的介怀。「既有动病，难入定门」——「动病」并非一次念头出现，而是<strong>念头出现以后，心没有自主能力，只能被它拖走</strong>。</p><p><strong>爱见思虑，是心荆棘</strong>——「有如良田，荆棘未诛，虽下种子，嘉苗不茂」：</p><table tabindex="0"><thead><tr><th>比喻</th><th>所指</th></tr></thead><tbody><tr><td>良田</td><td>本来以道为根的心</td></tr><tr><td>荆棘</td><td>爱著、成见和杂乱思虑</td></tr><tr><td>种子</td><td>修道方法</td></tr><tr><td>嘉苗</td><td>定慧与道德</td></tr></tbody></table><p>人可能阅读很多经典、练习许多方法，但若不处理根本习气，方法就会被旧有心行压制。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先有所爱 → 再形成维护所爱的见解 → 最后不断思虑怎样获得、保存和辩护</span></span></code></pre></div><p><strong>最深的病：「自是」</strong>——原文列出一类人：身居富贵或学备经史，言则慈俭而行则贪残，辩足以饰非、势足以威物，得则名己、过则尤人。这种病为何最深？因为其他病尚可能被察觉，而「自是」会保护所有病：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>贪欲出现 → 用道理合理化</span></span>
<span class="line"><span>行为错误 → 用辩才掩饰</span></span>
<span class="line"><span>别人指出 → 用权势压制</span></span>
<span class="line"><span>事情成功 → 证明自己正确</span></span>
<span class="line"><span>事情失败 → 归咎于别人</span></span></code></pre></div><p>一旦自以为是成为防御系统，经典知识反而会被用来装饰习气，所以「虽学无益」。</p><h3 id="五、心依境日久-必须「随起随制」-第五层" tabindex="-1">五、心依境日久，必须「随起随制」（第五层） <a class="header-anchor" href="#五、心依境日久-必须「随起随制」-第五层" aria-label="Permalink to &quot;五、心依境日久，必须「随起随制」（第五层）&quot;">​</a></h3><p><strong>此心犹来依境，未惯独立</strong>——心平常总要抓住一些东西（一个声音、一条信息、一段回忆、一个计划、一种情绪）。所以一旦「无所托」，它常会感到无聊、空虚、焦躁，想寻找刺激，甚至怀疑这样坐着是否有意义。<strong>这不是心不能安定，而是它尚未习惯。</strong></p><p><strong>乍无所托，难以自安</strong>——初学的常见经验：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>平时事务很多 → 杂念被事务遮掩</span></span>
<span class="line"><span>静坐无事 → 原有念头全部浮现</span></span>
<span class="line"><span>误以为静坐使心更乱 → 实际只是第一次清楚看见散乱</span></span></code></pre></div><p>故不应因初坐杂念多便否定方法。「纵得暂安，还复散乱」说明暂时状态尚未形成稳定能力；修习本就是反复过程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>散乱 → 察觉 → 收回 → 暂安 → 又散 → 再觉 → 再收</span></span></code></pre></div><p>每一次觉察与收回，都在减弱旧习、培养新习。</p><p><strong>随起随制，务令不动</strong>——「制」的重点不是禁止念头最初出现，而是阻止它继续扩展：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>想起一句毁誉 → 觉察 → 不继续辩解和想象</span></span>
<span class="line"><span>想起一件非当前事务 → 觉察 → 暂不处理 → 回到安住</span></span>
<span class="line"><span>生起修行评价 → 觉察 → 不继续判断得失</span></span></code></pre></div><p>这比「心起皆灭」温和，也比「任心所起」积极。「久久调熟，自得安闲」则是从有为进入无为的过程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初期：作意收摄 → 中期：散乱减少 → 后期：安定成习 → 最终：不收而自安</span></span></code></pre></div><p><strong>收心不只发生在静坐中</strong>——「无问昼夜，行住坐卧，及应事之时，常须作意安之」。若只在固定时段静坐，离座以后便任心放逸，定力很难稳固。行住坐卧中的收心不是时时紧绷，而是：知道自己正在做什么、不无意识地追随杂念、事情结束后及时放下。</p><p>「作意」说明初学尚不能完全自然，需要适当提醒——这不是一边做事一边维持僵硬的空境，而是<strong>不让必要行动演变成心理攀缘</strong>。</p><p>「若心得定，即须安养，莫有恼触」——初得定时力量尚弱，如同幼苗：不宜立刻投入繁杂境界测试自己，不宜主动参与是非争论，不宜炫耀体验。「莫有恼触」不是永远逃避生活，而是保护尚未成熟的定力。</p><p>「少得定分，即堪自乐」——这种内在安乐不依赖他人称赞、财物增加、感官刺激或神异体验，而是心不再持续外驰之后自然产生的轻安。一旦体验到，过去所爱的声色名利便会逐渐显得狭隘（「平生所爱，已嫌蔽陋」）——<strong>这不是靠道德命令强迫厌欲，而是有了更深安乐以后，旧有刺激自然失去部分吸引力。</strong></p><p>「况因定生慧，深达真假乎」是从【收心】通向【真观】的过渡：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初得定 → 体验不逐外物的安乐</span></span>
<span class="line"><span>由定生慧 → 看清欲望与境界的虚实</span></span>
<span class="line"><span>既有体验又有明见 → 执著才会从根本减弱</span></span></code></pre></div><p><strong>牛马与鹰鹯：为什么心必须调熟</strong>——</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>牛马家畜也，放纵不收，犹自生梗，不受驾驭</span></span>
<span class="line"><span>鹰鹯野鸟也，为人羁绊，终日在手，自然调熟</span></span></code></pre></div><p>两组比喻形成对照：家畜若放纵也会难驯，野鸟若调习也能渐熟。故：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>纵任外驰 → 唯益粗疏</span></span>
<span class="line"><span>随起随制 → 久久调熟 → 自得安闲</span></span></code></pre></div><p>（这只是古代调心比喻，不应理解为以暴力对待自己的心；真正方法仍是觉察、收回和长期安养。）心若粗疏散乱，就无法观察大道幽微之妙——<strong>「观妙」需要心具备稳定、清明、细致、不被欲望预设结论的品质；没有收心的定，便很难有【真观】的慧。</strong></p><p>「虽有拱璧，以先驷马，不如坐进此道」（《道德经》第六十二章）——外在珍宝不能代替心的返归，尊贵仪仗不能给予真正安定；修道贵在亲自坐进、切实行持。</p><h3 id="六、法贵能行-不贵能言-第六层" tabindex="-1">六、法贵能行，不贵能言（第六层） <a class="header-anchor" href="#六、法贵能行-不贵能言-第六层" aria-label="Permalink to &quot;六、法贵能行，不贵能言（第六层）&quot;">​</a></h3><p><strong>妙用在能行，不在能言</strong>——一句话是否真正被理解，要看它能否改变心行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能讲「不著」，却处处受毁誉影响 → 尚未真正理解不著</span></span>
<span class="line"><span>能讲「无为」，却不断强作生事   → 尚未真正理解无为</span></span>
<span class="line"><span>能讲「坐忘」，却执著自己的境界 → 尚未真正理解坐忘</span></span></code></pre></div><p>「行之则斯言为当，不行则斯言如妄」——亲实行持，语言才得到印证；若从不实行，再高明的话也近于虚妄。</p><p><strong>贵难而贱易</strong>——人常把难懂当作高深，把易行当作浅薄：若有人广谈虚无、使用无法理解的语言，人们反而容易惊叹「不可思议」；若有人把方法直说（念起即觉、非必要之事不思、事毕即止），人们却因太简单而轻视。这种心理来自「知识崇拜」：</p><blockquote><p><strong>我们容易以听不懂证明对方高深，却不愿以能否实行检验方法真假。</strong></p></blockquote><p>引《道德经》第七十章「吾言甚易知，甚易行，天下莫能知，莫能行」——困难不在概念，而在人的欲望与习惯不愿改变。「不逐毁誉」非常易懂，但遇到一句批评便会立刻反应；「简事」也很易懂，但面对机会时又不肯舍弃。<strong>这就是「知易行难」的真正所在。</strong></p><p><strong>「火不热，灯不照暗」：语言奇论不是修道</strong>——「火不热」等命题与先秦名家辩论有关（《庄子·天下》记录了一系列类似说法）。司马承祯并非要全面讨论名家哲学，而是批评一种修道风气：把违反常识的奇异言论，当成已证大道的标志。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语言上破除常识 + 行动中仍承认事实 = 言行相违</span></span></code></pre></div><p>人嘴上说火不热，实际仍靠火取暖；说灯不能照暗，夜里仍整晚点灯。若一种高论不能改变认识和实践，只是制造惊奇，就不能被当作修道成就。「破相之言」若只停留在语言，内心仍贪名、好辩、争胜，便只是以「破相」建立新的语言优越感。<strong>真正离相，不是把正常语言全部颠倒，而是不被名相和成见束缚，同时仍能如实应事。</strong>「虽惠子宏辩，庄生以为不堪」——辩才宏富不等于心已得定，概念奇异不等于生命已经转化。</p><p><strong>篇末问难：为什么不直接学圣人「处动不乱」</strong>——质疑者提出：既然大道是「在物而心不染，处动而神不乱」，为什么要避事取安、离动求定？这样反而制造了「动静二心」「取舍两病」。这是非常有力量的反驳。</p><p>司马承祯先承认最高境界：「在物而不染，处事而不乱，真为大矣，实为妙矣。」</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初学：离境收心 → 成熟：对境不染</span></span>
<span class="line"><span>初学：避事求安 → 成熟：处事不乱</span></span>
<span class="line"><span>初学：作意控制 → 成熟：无心自定</span></span></code></pre></div><p><strong>争论不在终点，而在能否跳过过程。</strong></p><p><strong>四个譬喻：不能只看成果，不问其来处</strong>——</p><ul><li><strong>「贝锦辉焕，始抽素丝」</strong>：华美锦缎最初也要从一根根朴素的丝线开始。只羡慕成品却轻视基础材料，便无法真正得到成品。</li><li><strong>「鸣鹤冲天，先资于𬆮食」</strong>（按底本保留「𬆮食」，相关版本或有异文）：白鹤能振翼冲天，最初也须经历幼小、受食与成长。</li><li><strong>「蔽日之干，起于毫末」</strong>（化用《道德经》第六十四章「合抱之木，生于毫末」）：定力看似自然宏大，实由无数次细小的「念起即觉、觉而不随」积累而成。</li><li><strong>「神凝至圣，积习而成」</strong>：</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>凡夫的散乱，是长期逐境积习而成</span></span>
<span class="line"><span>圣人的不乱，也是长期收心积习而成</span></span></code></pre></div><p><strong>「见卯而求时夜，见弹而求鸮炙」</strong>——底本作「卯」，常见文字作「卵」（见卵而求时夜）。「时夜」是司夜报晓之鸡：看见鸡蛋便立刻要求它成为报晓之鸡，显然跳过了孵化与生长过程；刚看见弹丸便要求吃到烤鸮肉，也跳过了射猎与烹制。二者同喻<strong>刚开始修心便要求具有圣人成熟的定力</strong>——故批评「何其造次哉」。</p><p><strong>「与物反，然后乃至大顺」</strong>（《道德经》第六十五章附近）——世俗心的自然惯性是向外追逐、增加事务、扩张占有、表现才能；修道初期却要反过来：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先与物反 → 逆转逐境习惯</span></span>
<span class="line"><span>再归于根 → 定慧成熟</span></span>
<span class="line"><span>最终大顺 → 处物而不染，应事而不乱</span></span></code></pre></div><p>因此次第不是永远停留在回避中，而是<strong>先有意识地逆转习气，最终达到不勉强、不对抗的自然大顺</strong>。</p><h3 id="引经据典" tabindex="-1">引经据典 <a class="header-anchor" href="#引经据典" aria-label="Permalink to &quot;引经据典&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书中引文／典故</th><th>出处</th><th>转化</th></tr></thead><tbody><tr><td>夫物芸芸，各归其根……知常曰明</td><td>《道德经》第十六章</td><td>由万物返根的宇宙论，转为调心次第：归根→静定→复命→知常</td></tr><tr><td>虽有拱璧，以先驷马，不如坐进此道</td><td>《道德经》第六十二章</td><td>外在珍宝不如心的返归，修道贵在亲自坐进</td></tr><tr><td>吾言甚易知，甚易行……是以不我知</td><td>《道德经》第七十章</td><td>困难不在概念，而在欲望与习惯不愿改变</td></tr><tr><td>火不热、灯不照暗</td><td>名家辩题（《庄子·天下》一系）</td><td>批评以语言奇论冒充修道成就，言行相违者不足取</td></tr><tr><td>蔽日之干，起于毫末</td><td>《道德经》第六十四章（化用）</td><td>定力由无数次「念起即觉」积累而成</td></tr><tr><td>玄德深矣，远矣，与物反矣，然后乃至大顺</td><td>《道德经》第六十五章</td><td>先与物反，逆转逐境习惯，最终自然大顺</td></tr><tr><td>见卵而求时夜，见弹而求鸮炙</td><td><a href="/Dao/daoism/zhuang-zi/chapter-02">《庄子·齐物论》</a></td><td>批评初学便求圣境，跳过孵化与射猎的过程</td></tr><tr><td>惠子宏辩，庄生以为不堪</td><td>《庄子》一系</td><td>辩才宏富不等于心已得定</td></tr></tbody></table><p>「至道之中，寂无所有」「人能虚心无为，非欲于道，道自归之」等仅称「经云」，暂待考——见<a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">《引经据典》</a>。</p><h3 id="与《天隐子》的对应" tabindex="-1">与《天隐子》的对应 <a class="header-anchor" href="#与《天隐子》的对应" aria-label="Permalink to &quot;与《天隐子》的对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>《天隐子》</th><th>本篇</th><th>呼应</th></tr></thead><tbody><tr><td>存想六（存我之神，想我之身；目终日视他人，故心亦逐外走）</td><td>收心（安坐·收心离境·随起随制）</td><td>一篇指出「逐外」的现象，一篇分析其机制与对治</td></tr><tr><td>安处五（调风气明暗，心目皆安）</td><td>学道之初，要须安坐</td><td>均不赞成初学者无视环境影响而自称「在物不染」</td></tr><tr><td>坐忘七（有见而不行其见；心不动，形都泯）</td><td>所有闻见，如不闻见；不著物而又不动</td><td>「忘」不是没有见闻，而是见闻不进入心中形成攀缘</td></tr><tr><td>坐忘七（因存想而得也，因存想而忘也）</td><td>作意安之 → 随起随制 → 久久调熟 → 自得安闲</td><td>先有意收心，最后连「我在收心」也不再突出</td></tr></tbody></table><h3 id="容易误解的地方" tabindex="-1">容易误解的地方 <a class="header-anchor" href="#容易误解的地方" aria-label="Permalink to &quot;容易误解的地方&quot;">​</a></h3><ol><li><strong>「安坐」不是只要坐得久</strong>——若身体坐着而心仍追逐外境，就尚未进入收心。</li><li><strong>「离境」不是否认世界</strong>——不是认为外物全不存在，而是不再使外物成为心的固定依托。</li><li><strong>「住无所有」不是大脑空白</strong>——真正的无所有保留清醒觉照；若失去觉知，后文称为「盲定」。</li><li><strong>「虚无」不是消极虚无主义</strong>——是心无所占有、无所黏著，因此能恢复开放与灵明，不是认为生命毫无意义。</li><li><strong>「心乃合道」不是制造合一体验</strong>——若急于追求「我与道合一」的感觉，心又执著于一种境界；真正的合道由不著而自然发生，所以说「自入虚无」。</li><li><strong>「心神被染」不等于外界都是罪恶</strong>——染污来自心对境的黏著，不单来自境本身。同一外境，有人因之贪著，有人可以如实应对而不留滞。</li><li><strong>「净除心垢」不是攻击自己</strong>——心垢是习惯与遮蔽，不是人的全部本质；若因杂念多而厌恶自己，新的厌恶又会成为心垢。</li><li><strong>执著于「空」也是执著</strong>——「若执心住空，还是有所」：物与空不同，执著的心理结构却相同。</li></ol><h3 id="本篇最重要的六个辨析" tabindex="-1">本篇最重要的六个辨析 <a class="header-anchor" href="#本篇最重要的六个辨析" aria-label="Permalink to &quot;本篇最重要的六个辨析&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不是</th><th>而是</th></tr></thead><tbody><tr><td>消灭一切念头</td><td>止息乱念，保留觉照</td></tr><tr><td>任心自然漂流</td><td>念起即觉，不再续接</td></tr><tr><td>执著空白无念</td><td>不著于物，也不著于空</td></tr><tr><td>永远逃避事务</td><td>初学减少扰动，成熟后应物不染</td></tr><tr><td>追求玄妙奇论</td><td>长期实行简易可行之法</td></tr><tr><td>一步模仿圣人</td><td>由作意收心，积习至于自然</td></tr></tbody></table><h3 id="修行逻辑" tabindex="-1">修行逻辑 <a class="header-anchor" href="#修行逻辑" aria-label="Permalink to &quot;修行逻辑&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一、心为一身之主、百神之帅；静则生慧，动则成昏</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>二、心因依托幻境而颠倒：心神被染，流浪日久</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>三、初学须安坐：收心离境，住无所有，不著一物，心乃合道</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>四、无复流浪名曰归根；守根不离名曰静定；静定日久，复命知常</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>五、不仅不能著物，也不能执心住空；真定是不著而不动</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>六、不可一概灭念，也不可任心所起；不可借无分别而放逸，</span></span>
<span class="line"><span>    更不可冒充「处事不染」</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>七、正确原则：息乱而不灭照，守静而不著空</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>八、必要问题可以思考，问题解决便须停止；不可用智慧反害恬静</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>九、毁誉是非来时不受不逐：心不受外名曰虚心，心不逐外名曰安心</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>十、爱见思虑是心中荆棘，其中最深的病是自是</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>十一、心依境日久，不能骤然自安：随起随制，久久调熟</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>十二、行住坐卧、应事之时，都要作意安养</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>十三、法贵能行，不贵能言；简单可行胜过玄谈奇论</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>十四、圣人能处动不乱，但这种自然来自长期积习</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>十五、初学先与物反，最后才能达到自然大顺</span></span></code></pre></div><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h3><p>【收心】真正要建立的，不是一颗完全没有活动的心，而是一颗<strong>有觉知而不攀缘、有智慧而不炫用、有应对而不留滞</strong>的心。</p><p>全篇最重要的三句话是：</p><blockquote><p><strong>但心不著物，又得不动，此是真定。</strong><strong>息乱而不灭照，守静而不著空。</strong><strong>随起随制，久久调熟，自得安闲。</strong></p></blockquote><p>三句分别说明：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真定的性质：不著而不动</span></span>
<span class="line"><span>收心的尺度：止乱而存照，守静而离空</span></span>
<span class="line"><span>修习的过程：由有意收摄，渐至自然安闲</span></span></code></pre></div><p>所以，【收心】不是强迫心立刻无念，也不是任它自由散乱，而是不断训练一种新的关系：</p><blockquote><p><strong>念可以出现，但不必追随；事可以处理，但不必留住；智慧可以使用，但用毕应重新归于恬静。</strong></p></blockquote><p>至此，【收心】完成了「定」的基本训练。但心暂时安定以后，现实生活中的事务仍然存在——哪些是性命所必需，哪些只是欲望的附加？这就进入下一篇<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-04">《简事》</a>。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/">《坐忘论》总览</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/guide">全书引读</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">引经据典</a></li><li>上一篇：<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-02">断缘二</a> · 下一篇：<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-04">简事四</a></li><li>引文出处：《道德经》第十六章（归根复命）、第六十二章（坐进此道）、第七十章（易知易行）、第六十四章（起于毫末）、第六十五章（玄德与物反）、<a href="/Dao/daoism/zhuang-zi/chapter-02">《庄子·齐物论》</a>（见卵见弹）</li><li>《天隐子》对应：<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-6">存想六</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-7">坐忘七</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-5">安处五</a></li></ul>`,185))])}const C=o(g,[["render",h]]);export{y as __pageData,C as default};
